'use strict';
(()=>{
const iconPaths={
 'layout-dashboard':'<rect x="3" y="3" width="8" height="8" rx="1.5"/><rect x="14" y="3" width="7" height="5" rx="1.5"/><rect x="14" y="11" width="7" height="10" rx="1.5"/><rect x="3" y="14" width="8" height="7" rx="1.5"/>',
 'briefcase-business':'<rect x="3" y="7" width="18" height="14" rx="2"/><path d="M8 7V5a2 2 0 0 1 2-2h4a2 2 0 0 1 2 2v2M3 12h18"/>',
 'panels-top-left':'<rect x="3" y="3" width="18" height="18" rx="2"/><path d="M3 9h18M9 9v12"/>',
 'list-checks':'<path d="m3 7 1.8 1.8L8 5.5M11 7h10M3 17l1.8 1.8L8 15.5M11 17h10"/>',
 'files':'<rect x="6" y="4" width="14" height="17" rx="2"/><path d="M3 17V3a1 1 0 0 1 1-1h12M9 9h8M9 13h8"/>',
 'bot':'<rect x="4" y="7" width="16" height="13" rx="3"/><path d="M12 3v4M9 3h6M8 13h.01M16 13h.01M9 17h6"/>',
 'blocks':'<rect x="3" y="3" width="7" height="7" rx="1"/><rect x="14" y="3" width="7" height="7" rx="1"/><rect x="3" y="14" width="7" height="7" rx="1"/><path d="M14 14h7v7h-7z"/>',
 'history':'<path d="M3 12a9 9 0 1 0 3-6.7L3 8V3m0 5h5M12 7v5l4 3"/>',
 'chevron-down':'<path d="m6 9 6 6 6-6"/>',
 'menu':'<path d="M4 6h16M4 12h16M4 18h16"/>',
 'search':'<circle cx="11" cy="11" r="7"/><path d="m16 16 5 5"/>',
 'arrow-right':'<path d="M5 12h14m-6-6 6 6-6 6"/>',
 'arrow-up-right':'<path d="M7 17 17 7M8 7h9v9"/>',
 'plus':'<path d="M12 5v14M5 12h14"/>',
 'shield-check':'<path d="m12 2 8 4v6c0 5-3.5 8.5-8 10-4.5-1.5-8-5-8-10V6z"/><path d="m9 12 2 2 4-4"/>',
 'check-square':'<rect x="3" y="3" width="18" height="18" rx="2"/><path d="m8 12 3 3 5-6"/>',
 'clock-3':'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l4 2"/>',
 'clock':'<circle cx="12" cy="12" r="9"/><path d="M12 7v5l4 2"/>',
 'network':'<rect x="9" y="3" width="6" height="5" rx="1"/><rect x="3" y="16" width="6" height="5" rx="1"/><rect x="15" y="16" width="6" height="5" rx="1"/><path d="M12 8v4M6 16v-4h12v4"/>',
 'flask-conical':'<path d="M9 3h6M10 3v7L4 20a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2l-6-10V3M7 16h10"/>',
 'file-check-2':'<path d="M6 3h9l5 5v14H6a2 2 0 0 1-2-2V5a2 2 0 0 1 2-2ZM14 3v6h6M8 15l2 2 4-4"/>',
 'chart-no-axes-column':'<path d="M5 21v-7h4v7M10 21V8h4v13M15 21V3h4v18"/>',
 'alert-circle':'<circle cx="12" cy="12" r="9"/><path d="M12 7v6M12 17h.01"/>',
 'x':'<path d="m5 5 14 14M19 5 5 19"/>',
 'check':'<path d="m4 12 5 5 11-11"/>',
 'file-text':'<path d="M5 3h9l5 5v13H5zM14 3v5h5M8 13h8M8 17h8"/>',
 'save':'<path d="M4 3h14l3 3v15H3V3zM7 3v7h10V3M7 21v-8h10v8"/>',
 'refresh-cw':'<path d="M20 11a8 8 0 0 0-14-5L3 9m0-6v6h6M4 13a8 8 0 0 0 14 5l3-3m0 6v-6h-6"/>',
 'filter':'<path d="M4 5h16l-6 7v7l-4 2v-9z"/>',
 'code':'<path d="m8 7-5 5 5 5m8-10 5 5-5 5M14 4l-4 16"/>',
 'git-branch':'<circle cx="6" cy="4" r="2"/><circle cx="6" cy="20" r="2"/><circle cx="18" cy="7" r="2"/><path d="M6 6v12M18 9a7 7 0 0 1-7 7H6"/>',
 'copy':'<rect x="8" y="8" width="13" height="13" rx="2"/><path d="M16 8V5a2 2 0 0 0-2-2H5a2 2 0 0 0-2 2v9a2 2 0 0 0 2 2h3"/>'
};
const ico=(name,cl='')=>`<svg class="svgicon ${cl}" viewBox="0 0 24 24" aria-hidden="true">${iconPaths[name]||iconPaths['blocks']}</svg>`;
document.querySelectorAll('i[data-icon]').forEach(el=>el.outerHTML=ico(el.dataset.icon));document.getElementById('brandIcon').innerHTML=ico('blocks','large');
const parse=id=>JSON.parse(document.getElementById(id).textContent);
const PACKS=parse('embeddedPacks');const FIXTURES=parse('embeddedCases').cases;
const PERSIST_KEY='casebase-ucw-prototype-v1';let saved=null;try{saved=JSON.parse(localStorage.getItem(PERSIST_KEY))}catch{}
const state={cases:saved?.cases||structuredClone(FIXTURES),currentCase:saved?.currentCase||FIXTURES[0].id,page:'overview',activeTab:saved?.activeTab||'overview',role:saved?.role||'editor',selectedPack:saved?.selectedPack||'sim.tender',filter:'',selectedArtifact:null,packPreview:'sim.tender',statusFilter:'all',audit:saved?.audit||[]};
const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const packFor=key=>PACKS.find(p=>p.pack_key===key);
const caze=()=>state.cases.find(c=>c.id===state.currentCase)||state.cases[0];
const currentPack=()=>packFor(caze().pack_key);
const persist=()=>{try{localStorage.setItem(PERSIST_KEY,JSON.stringify({cases:state.cases,currentCase:state.currentCase,activeTab:state.activeTab,selectedPack:state.selectedPack,role:state.role,audit:state.audit}))}catch{}};
const badge=(value)=>{const s=String(value||'');let css=/approved|verified|complete|published|done/i.test(s)?'green':/pending|review|draft|open|progress|partial/i.test(s)?'amber':/error|stale|rejected|blocked/i.test(s)?'red':'blue';return `<span class="pill ${css}">${esc(s)}</span>`};
const button=(label,action,cls='')=>`<button type="button" class="btn ${cls}" data-action="${esc(action)}">${label}</button>`;
const title=(name,sub,actions='')=>`<div class="pagehead"><div><h1>${name}</h1><p>${sub}</p></div><div class="actions">${actions}</div></div>`;
let tid;
const toast=msg=>{const el=document.getElementById('toast');el.textContent=msg;el.classList.add('show');clearTimeout(tid);tid=setTimeout(()=>el.classList.remove('show'),3400)};
const addAudit=(c,actor,action)=>{const item={at:'Just now',actor,action};c.audit.unshift(item);state.audit.unshift({case_id:c.id,...item});persist()};
const nav=where=>{state.page=where;document.querySelectorAll('.page').forEach(el=>el.classList.toggle('active',el.id==='page-'+where));document.querySelectorAll('.side-nav button').forEach(el=>el.classList.toggle('active',el.dataset.go===where));document.getElementById('breadcrumb').textContent={overview:'Overview',cases:'My Cases',workbench:'Case Workspace',tasks:'My Tasks',documents:'Documents',ai:'AI Activity',packs:'Domain Packs',activity:'Activity & Audit'}[where]||where;document.getElementById('sidebar').classList.remove('open');document.getElementById('mobileShade').classList.remove('open');render();window.scrollTo({top:0,behavior:'instant'})};
const openCase=id=>{const c=state.cases.find(x=>x.id===id);if(!c)return;state.currentCase=id;state.selectedPack=c.pack_key;state.activeTab='overview';persist();nav('workbench')};
const pair=(a,b)=>`<div class="datapair"><span>${esc(a)}</span><strong>${esc(b)}</strong></div>`;
const genericCaseStatus=()=>{const cas=state.cases;return {open:cas.length,review:cas.filter(c=>/review/i.test(c.status)).length,tasks:cas.reduce((n,c)=>n+c.tasks.filter(t=>t.status==='Open').length,0)}};
function renderOverview(){const stats=genericCaseStatus(),c=caze();const el=document.getElementById('page-overview');el.innerHTML=title('Good afternoon, team ✳','One workbench. Different business workflows. Shared governance.',button(`${ico('plus','small')} Browse cases`,'nav:cases','primary'))+`<div class="bento"><div class="hero"><small>ONE REUSABLE EXPERIENCE LAYER</small><h2>Every business case.<br>One familiar workspace.</h2><p>Run domain-specific work on top of Flowcase, KMS and Agent Studio—without rebuilding the app.</p>${button(`Open active case ${ico('arrow-right','small')}`,'nav:workbench')}</div><div class="metric feature"><div class="metric-icon">${ico('briefcase-business','large')}</div><small>Cases in workspace</small><strong>${stats.open.toString().padStart(2,'0')}</strong><span>Across 3 domain templates</span></div><div class="metric"><div class="metric-icon">${ico('shield-check','large')}</div><small>Cases in review</small><strong>${stats.review.toString().padStart(2,'0')}</strong><span>Human decisions remain in Flowcase</span></div></div>
<div class="overview-grid"><div class="stack"><div class="card"><div class="cardhead card-top"><div><h2>Recent cases</h2><p>Different domains, one consistent experience</p></div><button class="small-link" data-action="nav:cases">All cases ↗</button></div>${caseTable(state.cases.slice(0,4))}</div><div class="card pad"><div class="cardhead"><div><h2>Reusable by design</h2><p>Capabilities this workbench composes from existing services</p></div></div><div class="grid3">${[['Flowcase','Case, workflow, tasks, approvals','git-branch'],['KMS','Documents, citations, knowledge','files'],['Agent Studio','AI execution, versions, traces','bot']].map(x=>`<div class="ministat" style="background:#f8fbff"><div class="square">${ico(x[2])}</div><b style="display:block;margin-top:10px;font-size:11px">${x[0]}</b><small>${x[1]}</small></div>`).join('')}</div></div></div><div class="stack"><div class="card pad"><div class="cardhead"><div><h2>Needs your attention</h2><p>From assigned domain cases</p></div>${badge(stats.tasks+' open tasks')}</div>${state.cases.flatMap(c=>c.tasks.filter(t=>t.status==='Open').map(t=>({c,t}))).slice(0,4).map(({c,t})=>`<div class="queue"><div class="square amber">${ico('clock','small')}</div><div style="flex:1"><strong>${esc(t.title)}</strong><p>${esc(c.id)} · ${esc(t.assignee)}</p></div><button class="small-link" data-action="open:${esc(c.id)}">Open</button></div>`).join('')}</div><div class="card pad"><div class="cardhead"><div><h2>Domain Packs</h2><p>Configuration-driven modules</p></div><button class="small-link" data-action="nav:packs">Browse ↗</button></div>${PACKS.map(p=>`<div class="queue"><div class="square">${ico(p.brand?.icon||'blocks','small')}</div><div><strong>${esc(p.title)}</strong><p>${p.navigation.length} modules · ${p.artifact_types.length} artifact types</p></div>${badge(p.status)}</div>`).join('')}</div></div></div>`}
function caseTable(cases){return `<div class="table-scroll"><table class="table"><thead><tr><th>CASE</th><th>DOMAIN PACK</th><th>STAGE</th><th>OWNER</th><th>STATUS</th><th></th></tr></thead><tbody>${cases.map(c=>`<tr><td><strong>${esc(c.name)}</strong><small>${esc(c.id)} · ${esc(c.organization)}</small></td><td>${esc(packFor(c.pack_key)?.title||'Unknown pack')}<small>Pinned v${esc(c.pack_version)}</small></td><td>${esc(c.current_stage)}</td><td>${esc(c.owner)}</td><td>${badge(c.status)}</td><td>${button('Open','open:'+c.id,'sm soft')}</td></tr>`).join('')||'<tr><td colspan="6" class="muted">No cases found.</td></tr>'}</tbody></table></div>`}
function renderCases(){const options=PACKS.map(p=>`<option value="${esc(p.pack_key)}" ${state.selectedPack===p.pack_key?'selected':''}>${esc(p.title)}</option>`).join('');const list=state.cases.filter(c=>(state.selectedPack==='all'||c.pack_key===state.selectedPack)&&(`${c.id} ${c.name} ${c.organization} ${c.owner}`.toLowerCase().includes(state.filter.toLowerCase())));document.getElementById('page-cases').innerHTML=title('My Cases','Open an authorized case to load its pinned Domain Pack.',button('View Domain Packs','nav:packs'))+`<div class="filters"><div class="filters-left"><input id="caseSearch" class="input search" placeholder="Search cases, owner, organization..." aria-label="Search cases" value="${esc(state.filter)}"><select id="casePackFilter" class="select" aria-label="Filter by domain"><option value="all" ${state.selectedPack==='all'?'selected':''}>All domains</option>${options}</select></div><span class="muted tiny">${list.length} matching cases · fixture data</span></div><div class="card">${caseTable(list)}</div>`}
function renderWorkbench(){const c=caze(),pack=currentPack();if(!pack){document.getElementById('page-workbench').innerHTML=title('Workspace unavailable','Pinned domain pack is missing.')+'<div class="notice warning">The case can only open read-only until its exact pack version is restored.</div>';return}const tab=pack.navigation.find(n=>n.key===state.activeTab)||pack.navigation[0];const tabRender=renderCaseTab(c,pack,tab);document.getElementById('page-workbench').innerHTML=title('Case Workspace',`${esc(pack.title)} · pack v${esc(c.pack_version)} · workflow v${esc(c.workflow_version)}`,button('All cases','nav:cases')+button('Change case','nav:cases','soft'))+`<div class="case-head"><div style="flex:1"><div style="display:flex;align-items:center;gap:8px;margin-bottom:7px">${badge(c.status)} <span class="pill blue">${esc(c.id)}</span></div><h2>${esc(c.name)}</h2><p>${esc(c.organization)} · ${esc(c.owner)} · Due ${esc(c.due)}</p></div><div class="actions"><span class="pill blue">${esc(c.current_stage)}</span>${button(ico('arrow-up-right','small')+' Domain pack','nav:packs','sm soft')}</div></div><div class="stages">${c.stages.map((stage,i)=>`<div class="stage ${esc(stage.state)}"><div class="stage-num">${stage.state==='done'?ico('check','small'):i+1}</div><div><strong>${esc(stage.label)}</strong><small>${stage.state==='done'?'Completed':stage.state==='current'?'Current stage':'Pending'}</small></div></div>`).join('')}</div><div class="case-layout"><div class="case-main"><div class="case-tabs" id="caseTabs">${pack.navigation.map(n=>`<button type="button" data-tab="${esc(n.key)}" class="${n.key===tab.key?'active':''}">${ico(n.icon||'blocks','small')} ${esc(n.label)}</button>`).join('')}</div>${tabRender}</div><aside class="case-rail"><div class="card pad"><div class="cardhead"><div><h3>Context & decisions</h3><p>Flowcase is authoritative</p></div></div>${c.approvals.slice(0,3).map(a=>`<div class="listline"><div class="square ${a.status==='Pending'?'amber':'green'}">${ico('shield-check','small')}</div><div><strong>${esc(a.name)}</strong><p>${esc(a.approver)} · ${esc(a.version_ref)}</p>${badge(a.status)}</div></div>`).join('')}</div><div class="card pad"><div class="cardhead"><div><h3>Contextual AI</h3><p>Agent Studio · allowed actions</p></div></div>${pack.actions.filter(a=>a.executor==='agent_invocation').map(a=>`<div class="listline"><div class="square">${ico('bot','small')}</div><div style="flex:1"><strong>${esc(a.label)}</strong><p>${esc(a.agent_key)} · draft output</p></div><button class="btn sm soft" data-action="agent:${esc(a.key)}">Run</button></div>`).join('')||'<p class="muted tiny">No configured AI actions.</p>'}<div class="notice warning" style="margin-top:13px">Agent outputs are drafts; no AI approval authority.</div></div><div class="card pad"><div class="cardhead"><h3>Evidence sources</h3></div>${c.documents.slice(0,2).map(d=>`<div class="listline"><div class="square">${ico('file-text','small')}</div><div><strong>${esc(d.title)}</strong><p>${esc(d.kms_ref)} · ${esc(d.version)}</p></div></div>`).join('')}</div></aside></div>`}
function renderCaseTab(c,pack,tab){switch(tab.view){
case 'overview':return `<div class="card pad"><div class="cardhead"><div><h2>Current case overview</h2><p>Workflow, artifacts and review tasks — same shell for every domain</p></div>${badge(c.status)}</div><div class="detail-columns"><div class="ministat"><strong>${c.artifacts.length}</strong><small>Versioned artifacts</small></div><div class="ministat"><strong>${c.tasks.filter(x=>x.status==='Open').length}</strong><small>Open tasks</small></div><div class="ministat"><strong>${c.progress}%</strong><small>Workflow progress</small></div></div><div style="margin:18px 0" class="notice">Workspace UI is generated from <b>${esc(pack.pack_key)}@${esc(pack.version)}</b>; business decisions remain in Flowcase.</div><div class="cardhead"><h3>Recent artifacts</h3>${button('View artifacts','tab:'+(pack.navigation.find(x=>x.view==='artifact_list')?.key||'overview'),'sm soft')}</div>${c.artifacts.map(a=>{const t=pack.artifact_types.find(x=>x.key===a.type);return `<div class="listline"><div class="square">${ico('file-text','small')}</div><div style="flex:1"><strong>${esc(t?.title||a.type)} · ${esc(a.id)}</strong><p>Revision ${a.version} · ${esc(a.updated_by)}</p></div>${badge(a.status)}</div>`}).join('')||'<div class="muted">No artifacts.</div>'}</div>`;
case 'artifact_list':{const type=pack.artifact_types.find(x=>x.key===tab.artifact_type);if(!type)return '<div class="notice warning">Missing referenced artifact type.</div>';let records=c.artifacts.filter(a=>a.type===type.key);let fields=type.fields.slice(0,3);return `<div class="card"><div class="cardhead card-top"><div><h2>${esc(type.title)}</h2><p>${esc(type.description)}</p></div><span class="pill blue">${records.length} records</span></div><div class="table-scroll"><table class="table"><thead><tr><th>ARTIFACT / REVISION</th>${fields.map(f=>`<th>${esc(f.label)}</th>`).join('')}<th>REVIEW STATE</th><th></th></tr></thead><tbody>${records.map(a=>`<tr><td><strong>${esc(a.id)}</strong><small>v${a.version} · ${esc(a.updated_by)}</small></td>${fields.map(f=>`<td>${esc(String(a.data[f.key]??'').slice(0,85))}</td>`).join('')}<td>${badge(a.status)}</td><td>${button('Inspect','artifact:'+a.id,'sm soft')}</td></tr>`).join('')||`<tr><td colspan="${fields.length+3}" class="muted">No artifacts yet. AI can propose a draft.</td></tr>`}</tbody></table></div></div><div class="notice" style="margin-top:14px">Field definitions, table labels and editor widgets come from the published Domain Pack. Saving edits creates a new draft revision, not an approval.</div>`}
case 'tasks':return `<div class="card pad"><div class="cardhead"><div><h2>Assigned work</h2><p>Task records and permissions come from Flowcase</p></div>${badge(c.tasks.length+' tasks')}</div>${c.tasks.map(t=>`<div class="listline"><div class="square amber">${ico('list-checks','small')}</div><div style="flex:1"><strong>${esc(t.title)}</strong><p>${esc(t.assignee)} · ${esc(t.due)} · ${esc(t.id)}</p></div>${badge(t.status)}${t.status==='Open'?button('Complete (demo)','task:'+t.id,'sm soft'):''}</div>`).join('')}</div>`;
case 'approvals':return `<div class="card pad"><div class="cardhead"><div><h2>Review & decisions</h2><p>Every approval remains a human Flowcase action tied to an artifact version</p></div></div><div class="notice warning">This demo never approves a business gate. The production backend must delegate decisions to an authorized Flowcase reviewer.</div>${c.approvals.map(a=>`<div class="listline"><div class="square">${ico('shield-check','small')}</div><div style="flex:1"><strong>${esc(a.name)}</strong><p>${esc(a.approver)} · ${esc(a.version_ref)}</p></div>${badge(a.status)}${a.status==='Pending'?button('View request','review:'+a.id,'sm soft'):''}</div>`).join('')}</div>`;
case 'documents':return `<div class="card pad"><div class="cardhead"><div><h2>Documents & Evidence</h2><p>KMS source ID, version and ACL remain authoritative</p></div>${badge(c.documents.length+' sources')}</div>${c.documents.map(d=>`<div class="listline"><div class="square">${ico('files','small')}</div><div style="flex:1"><strong>${esc(d.title)}</strong><p>${esc(d.kms_ref)} · ${esc(d.version)} · ${esc(d.pages)} pages</p></div>${badge(d.status)}${button('Details','document:'+d.id,'sm soft')}</div>`).join('')}</div>`;
case 'ai_activity':return `<div class="card pad"><div class="cardhead"><div><h2>AI Activity & Actions</h2><p>Registered Agent Studio identities only; tool scope enforced by backend</p></div></div>${pack.actions.filter(x=>x.executor==='agent_invocation').map(a=>`<div class="listline"><div class="square">${ico('bot','small')}</div><div style="flex:1"><strong>${esc(a.label)}</strong><p>${esc(a.agent_key)} · target ${esc(a.output_artifact_type||'draft')}</p></div>${button('Run demo','agent:'+a.key,'sm primary')}</div>`).join('')}<hr style="border:0;border-top:1px solid #eaf0f7;margin:20px 0"><h3 style="font-size:13px">Recent runs</h3>${c.runs.map(r=>`<div class="listline"><div class="square">${ico('clock','small')}</div><div style="flex:1"><strong>${esc(r.agent)} · ${esc(r.id)}</strong><p>${esc(r.time)} · pinned v${esc(r.version)}</p></div>${badge(r.status)}</div>`).join('')||'<p class="muted tiny">No executions yet.</p>'}</div>`;
case 'timeline':return `<div class="card pad"><div class="cardhead"><div><h2>Case timeline</h2><p>Service-originated events should carry source, actor and correlation ID</p></div></div>${c.audit.map(a=>`<div class="listline"><div class="square">${ico('history','small')}</div><div><strong>${esc(a.action)}</strong><p>${esc(a.actor)} · ${esc(a.at)}</p></div></div>`).join('')||'<p class="muted">No activity.</p>'}</div>`;
case 'extension':return '<div class="notice warning">This extension is not installed in the generic prototype. Production requires an allowlisted signed extension.</div>';
default:return '<div class="notice warning">Unsupported module view.</div>';
}}
function renderTasks(){let all=state.cases.flatMap(c=>c.tasks.map(t=>({c,t})));document.getElementById('page-tasks').innerHTML=title('My Tasks','Cross-domain task inbox sourced from Flowcase.')+`<div class="card"><div class="table-scroll"><table class="table"><thead><tr><th>TASK</th><th>CASE</th><th>ASSIGNEE</th><th>DUE</th><th>STATUS</th><th></th></tr></thead><tbody>${all.map(({c,t})=>`<tr><td><strong>${esc(t.title)}</strong><small>${esc(t.id)}</small></td><td>${esc(c.id)}</td><td>${esc(t.assignee)}</td><td>${esc(t.due)}</td><td>${badge(t.status)}</td><td>${button('Open case','open:'+c.id,'sm soft')}</td></tr>`).join('')}</tbody></table></div></div>`}
function renderDocuments(){const all=state.cases.flatMap(c=>c.documents.map(d=>({c,d})));document.getElementById('page-documents').innerHTML=title('Documents & Evidence','KMS metadata and exact source versions — without a second document service.')+`<div class="card"><div class="table-scroll"><table class="table"><thead><tr><th>DOCUMENT</th><th>KMS REFERENCE</th><th>CASE</th><th>STATUS</th><th></th></tr></thead><tbody>${all.map(({c,d})=>`<tr><td><strong>${esc(d.title)}</strong><small>${esc(d.pages)} pages</small></td><td>${esc(d.kms_ref)} · ${esc(d.version)}</td><td>${esc(c.id)}</td><td>${badge(d.status)}</td><td>${button('View case','open:'+c.id,'sm soft')}</td></tr>`).join('')}</tbody></table></div></div><div class="notice" style="margin-top:15px">Document details and page links require a real authorized KMS API response. This HTML never invents a live source URL.</div>`}
function renderAI(){const all=state.cases.flatMap(c=>c.runs.map(r=>({c,r})));document.getElementById('page-ai').innerHTML=title('AI Activity','Published agents execute in Agent Studio. Casebase displays run outcomes and proposed artifacts.')+`<div class="card"><div class="table-scroll"><table class="table"><thead><tr><th>RUN</th><th>AGENT</th><th>CASE</th><th>VERSION</th><th>STATUS</th><th></th></tr></thead><tbody>${all.map(({c,r})=>`<tr><td><strong>${esc(r.id)}</strong><small>${esc(r.time)}</small></td><td>${esc(r.agent)}</td><td>${esc(c.id)}</td><td>${esc(r.version)}</td><td>${badge(r.status)}</td><td>${button('Open case','open:'+c.id,'sm soft')}</td></tr>`).join('')}</tbody></table></div></div>`}
function validatePack(pack){const errors=[];const types=new Set(pack.artifact_types.map(t=>t.key));const keys=pack.navigation.map(n=>n.key);const actionKeys=pack.actions.map(a=>a.key);if(new Set(keys).size!==keys.length)errors.push('Duplicate navigation keys.');if(new Set(actionKeys).size!==actionKeys.length)errors.push('Duplicate action keys.');for(const n of pack.navigation){if(n.view==='artifact_list'&&!types.has(n.artifact_type))errors.push('Missing artifact type: '+n.artifact_type);if(n.view==='extension')errors.push('Extension requires server-installed registry verification.')}for(const a of pack.actions){if(a.executor==='agent_invocation'&&!pack.bindings.agent_keys.includes(a.agent_key))errors.push('Unregistered agent binding: '+a.agent_key);if(a.output_artifact_type&&!types.has(a.output_artifact_type))errors.push('Unknown output artifact type: '+a.output_artifact_type)}return errors}
function renderPacks(){const pack=packFor(state.packPreview)||PACKS[0];const errors=validatePack(pack);document.getElementById('page-packs').innerHTML=title('Domain Pack Library','Reusable workspace definitions. Different domain experiences, same UI engine.',button(`${ico('code','small')} View manifest`,'manifest','soft'))+`<div class="grid3" style="margin-bottom:16px">${PACKS.map(p=>`<div class="card pack-card"><div style="display:flex;justify-content:space-between;align-items:flex-start"><div class="pack-icon">${ico(p.brand?.icon||'blocks','large')}</div>${badge('v'+p.version)}</div><h3>${esc(p.title)}</h3><p>${esc(p.description)}</p><div class="pack-footer"><span class="muted tiny">${p.navigation.length} modules · ${p.artifact_types.length} artifact types</span>${button('Preview','pack:'+p.pack_key,'sm soft')}</div></div>`).join('')}</div><div class="grid2"><div class="card pad"><div class="cardhead"><div><h2>Selected manifest</h2><p>${esc(pack.pack_key)}@${esc(pack.version)} · ${esc(pack.status)}</p></div>${badge(errors.length?'Warnings':'Local checks pass')}</div>${pair('Flowcase binding',pack.bindings.flowcase_workflow_key)}${pair('Artifact provider',pack.bindings.artifact_provider)}${pair('Navigation tabs',String(pack.navigation.length))}${pair('Artifact schemas',String(pack.artifact_types.length))}${pair('Agent actions',String(pack.actions.filter(a=>a.executor==='agent_invocation').length))}<div class="notice" style="margin-top:16px">This pack is version-pinned per case. Publishing vNext does not migrate existing cases automatically.</div></div><div class="card pad"><div class="cardhead"><div><h2>Manifest configuration</h2><p>Read-only JSON inspector · local semantic checks</p></div>${button('Copy JSON','copyPack','sm soft')}</div><div class="codebox" id="packJSON">${esc(JSON.stringify(pack,null,2))}</div><p class="muted-mini" style="margin-top:10px">Server must also validate JSON Schema, permissions, workflow/agent references and signed extensions.</p></div></div>`}
function renderActivity(){const all=[...state.audit,...state.cases.flatMap(c=>c.audit.map(x=>({case_id:c.id,...x})))];document.getElementById('page-activity').innerHTML=title('Activity & Audit','Demo event projection. Production audit remains with the authoritative service.',button('Reset demo','reset','soft'))+`<div class="card pad">${all.map(x=>`<div class="listline"><div class="square">${ico('history','small')}</div><div style="flex:1"><strong>${esc(x.action)}</strong><p>${esc(x.case_id)} · ${esc(x.actor)} · ${esc(x.at)}</p></div></div>`).join('')||'<p class="muted tiny">No events.</p>'}</div>`}
function render(){document.getElementById('caseCount').textContent=state.cases.length;document.getElementById('roleSwitch').value=state.role;renderOverview();renderCases();renderWorkbench();renderTasks();renderDocuments();renderAI();renderPacks();renderActivity();document.querySelectorAll('.page').forEach(el=>el.classList.toggle('active',el.id==='page-'+state.page));persist()}
let openedArtifact=null;
function openArtifact(id){const c=caze(),pack=currentPack();const a=c.artifacts.find(x=>x.id===id);if(!a)return;const type=pack.artifact_types.find(t=>t.key===a.type);if(!type)return;openedArtifact=id;const readOnly=state.role==='viewer';document.getElementById('drawerTitle').textContent=type.title;document.getElementById('drawerSubtitle').textContent=`${a.id} · rev ${a.version} · ${a.status}`;document.getElementById('drawerBody').innerHTML=`<div class="notice ${a.status.includes('draft')?'warning':''}">Source of truth: registered ArtifactProvider. Editing creates a new draft revision; does not mark approved or perform a Flowcase decision.</div><div style="margin-top:17px" id="artifactFields">${type.fields.map(f=>{const val=a.data[f.key]??'';let control='';if(f.widget==='select')control=`<select class="select" id="art_${esc(f.key)}" ${readOnly||f.read_only?'disabled':''}>${(f.options||[]).map(op=>`<option value="${esc(op)}" ${String(val)===op?'selected':''}>${esc(op)}</option>`).join('')}</select>`;else if(f.widget==='textarea')control=`<textarea class="textarea" id="art_${esc(f.key)}" ${readOnly||f.read_only?'readonly':''}>${esc(val)}</textarea>`;else if(f.widget==='boolean')control=`<input type="checkbox" id="art_${esc(f.key)}" ${val?'checked':''} ${readOnly||f.read_only?'disabled':''}>`;else control=`<input class="input" id="art_${esc(f.key)}" type="${f.widget==='number'?'number':f.widget==='date'?'date':'text'}" ${f.min!=null?'min='+Number(f.min):''} ${f.max!=null?'max='+Number(f.max):''} value="${esc(val)}" ${readOnly||f.read_only?'readonly':''}>`;return `<div class="field"><label class="label" for="art_${esc(f.key)}">${esc(f.label)} ${f.required?'*':''}</label>${control}${f.hint?`<div class="hint">${esc(f.hint)}</div>`:''}</div>`}).join('')}</div><div class="datapair"><span>Artifact status</span>${badge(a.status)}</div>${pair('Revision',String(a.version))}${pair('Last author',a.updated_by)}${pair('Evidence authority','KMS source/version ACL')}<div class="notice warning" style="margin-top:15px">Typed evidence refs are not independently verified by this demo. Real KMS adapter must verify every source and ACL.</div><div style="margin-top:15px"><b style="font-size:12px">History</b>${(a.history||[]).map(h=>`<div class="listline"><div class="square">${ico('history','small')}</div><div><strong>v${h.version} · ${esc(h.status)}</strong><p>${esc(h.updated_by)}</p></div></div>`).join('')||'<div class="muted tiny" style="margin-top:7px">No prior revisions in fixture.</div>'}</div>`;
document.getElementById('drawerFoot').innerHTML=`${button('Close','closeDrawer')}${readOnly?'':button(`${ico('save','small')} Save draft revision`,'saveArtifact','primary')}`;document.getElementById('drawerBack').classList.add('show');document.getElementById('drawer').classList.add('show');}
function closeDrawer(){document.getElementById('drawerBack').classList.remove('show');document.getElementById('drawer').classList.remove('show');openedArtifact=null}
function saveArtifact(){if(state.role==='viewer'){toast('Viewer cannot edit artifacts in this demo.');return}const c=caze(),a=c.artifacts.find(x=>x.id===openedArtifact),pack=currentPack(),type=pack.artifact_types.find(t=>t.key===a.type);if(!a)return;const copy=structuredClone(a);const data=structuredClone(a.data);for(const f of type.fields){if(f.read_only)continue;const el=document.getElementById('art_'+f.key);if(!el)continue;let val=f.widget==='boolean'?el.checked:f.widget==='number'?(el.value===''?null:Number(el.value)):el.value;if(f.required&&(val===null||String(val).trim()==='')){toast('Required field: '+f.label);el.focus();return}if(f.widget==='number'&&val!==null&&((f.min!=null&&val<f.min)||(f.max!=null&&val>f.max))){toast('Out-of-range number: '+f.label);el.focus();return}data[f.key]=val}a.history=a.history||[];a.history.unshift({version:copy.version,status:copy.status,updated_by:copy.updated_by,data:copy.data});a.version++;a.data=data;a.status='Human draft';a.updated='Just now';a.updated_by='Demo editor';addAudit(c,'Demo editor','Updated '+a.id+' draft revision v'+a.version);closeDrawer();render();toast('Draft revision saved locally. Prior revision retained; no approval.');}
function runAgent(actionKey){const c=caze(),p=currentPack(),act=p.actions.find(a=>a.key===actionKey&&a.executor==='agent_invocation');if(!act)return toast('Agent action unavailable.');if(state.role==='viewer')return toast('Viewer cannot invoke agents in this demo.');const version='published-fixture';let id='run-demo-'+Math.random().toString(36).slice(2,7);c.runs.unshift({id,agent:act.agent_key,version,status:'Draft ready',time:'Just now'});let type=p.artifact_types.find(x=>x.key===act.output_artifact_type);if(type){let data={};for(const f of type.fields){if(f.widget==='select')data[f.key]=f.options?.[0]||'';else if(f.widget==='number')data[f.key]=f.min??0;else if(f.widget==='boolean')data[f.key]=false;else if(f.widget==='evidence_ref')data[f.key]='';else if(f.read_only)data[f.key]='AI-'+String(c.artifacts.length+1).padStart(3,'0');else data[f.key]='AI-proposed draft — verify source and assumptions';}c.artifacts.unshift({id:'draft-'+Math.random().toString(36).slice(2,7),type:type.key,version:1,status:'AI draft',data,updated_by:act.agent_key+' (simulated)',updated:'Just now'});}addAudit(c,'Agent Studio (mock)','Produced AI draft via '+act.agent_key);state.activeTab=p.navigation.find(n=>n.view==='artifact_list'&&n.artifact_type===act.output_artifact_type)?.key||'ai';render();toast('Simulated agent run created a draft. No real LLM called.');}
function completeTask(id){if(state.role==='viewer')return toast('Viewer cannot complete tasks.');let c=caze(),t=c.tasks.find(x=>x.id===id);if(!t||t.status!=='Open')return;t.status='Completed (demo)';addAudit(c,'Demo editor','Completed task '+id+' (local only)');render();toast('Local task updated. No Flowcase action was executed.');}
function showReview(id){let c=caze(),a=c.approvals.find(x=>x.id===id);if(!a)return;document.getElementById('modalTitle').textContent=a.name;document.getElementById('modalDescription').textContent='Flowcase owns reviewer decisions. This local UI cannot approve gates.';document.getElementById('modalFields').innerHTML=`${pair('Review item',a.id)}${pair('Responsible',a.approver)}${pair('Bound version',a.version_ref)}<div class="notice warning" style="margin-top:13px">Submit a decision only through the real Flowcase authorization and version checks. This preview displays metadata only.</div>`;document.getElementById('modalSubmit').textContent='Acknowledge';document.getElementById('modalBack').classList.add('show')}
function closeModal(){document.getElementById('modalBack').classList.remove('show')}
function inspectDocument(id){const c=caze(),doc=c.documents.find(d=>d.id===id);if(!doc)return;document.getElementById('drawerTitle').textContent=doc.title;document.getElementById('drawerSubtitle').textContent='KMS evidence reference · read-only metadata';document.getElementById('drawerBody').innerHTML=pair('Source reference',doc.kms_ref)+pair('Pinned version',doc.version)+pair('Pages',String(doc.pages))+pair('Status',doc.status)+'<div class="notice warning" style="margin-top:15px">A real document viewer or deep link requires an authorized URL returned by KMS. This prototype has no document bytes.</div>';document.getElementById('drawerFoot').innerHTML=button('Close','closeDrawer');document.getElementById('drawerBack').classList.add('show');document.getElementById('drawer').classList.add('show')}
function selectPack(key){const p=packFor(key);if(!p)return;state.packPreview=key;state.selectedPack=key;renderPacks();persist();toast('Previewed '+p.title+'. Existing cases remain pinned.');}
function action(a){if(a.startsWith('nav:'))return nav(a.slice(4));if(a.startsWith('open:'))return openCase(a.slice(5));if(a.startsWith('tab:')){state.activeTab=a.slice(4);renderWorkbench();persist();return}if(a.startsWith('artifact:'))return openArtifact(a.slice(9));if(a.startsWith('agent:'))return runAgent(a.slice(6));if(a.startsWith('task:'))return completeTask(a.slice(5));if(a.startsWith('review:'))return showReview(a.slice(7));if(a.startsWith('document:'))return inspectDocument(a.slice(9));if(a.startsWith('pack:'))return selectPack(a.slice(5));switch(a){case 'saveArtifact':return saveArtifact();case 'closeDrawer':return closeDrawer();case 'manifest':state.packPreview=currentPack().pack_key;nav('packs');return;case 'copyPack':{const p=packFor(state.packPreview);if(navigator.clipboard?.writeText)navigator.clipboard.writeText(JSON.stringify(p,null,2)).then(()=>toast('Manifest JSON copied')).catch(()=>toast('Clipboard unavailable'));else toast('Clipboard unavailable');return}case 'reset':if(confirm('Reset local workspace demo data?')){state.cases=structuredClone(FIXTURES);state.audit=[];state.currentCase=FIXTURES[0].id;state.activeTab='overview';render();toast('Demo reset.')}return;default:toast('Action is not available in this demo.')}}
document.addEventListener('click',e=>{let b=e.target.closest('[data-action]');if(b){e.preventDefault();action(b.dataset.action);return}let navb=e.target.closest('[data-go]');if(navb){nav(navb.dataset.go);return}let tab=e.target.closest('[data-tab]');if(tab){state.activeTab=tab.dataset.tab;renderWorkbench();persist();return}});
document.getElementById('menuButton').addEventListener('click',()=>{document.getElementById('sidebar').classList.add('open');document.getElementById('mobileShade').classList.add('open')});document.getElementById('mobileShade').addEventListener('click',()=>{document.getElementById('sidebar').classList.remove('open');document.getElementById('mobileShade').classList.remove('open')});document.getElementById('drawerClose').addEventListener('click',closeDrawer);document.getElementById('drawerBack').addEventListener('click',closeDrawer);document.getElementById('modalCancel').addEventListener('click',closeModal);document.getElementById('modalBack').addEventListener('click',e=>{if(e.target.id==='modalBack')closeModal()});document.getElementById('modalForm').addEventListener('submit',e=>{e.preventDefault();closeModal();toast('No real Flowcase decision executed.')});
document.getElementById('roleSwitch').addEventListener('change',e=>{state.role=e.target.value;render();toast('Demo UI role changed. Production permissions come from verified Control Plane and backend policies.');});
document.getElementById('topSearch').addEventListener('click',()=>{state.selectedPack='all';nav('cases');document.getElementById('caseSearch').focus()});
document.addEventListener('input',e=>{if(e.target.id==='caseSearch'){state.filter=e.target.value;const c=state.cases.filter(x=>(state.selectedPack==='all'||x.pack_key===state.selectedPack)&&(`${x.id} ${x.name} ${x.organization} ${x.owner}`.toLowerCase().includes(state.filter.toLowerCase())));const container=document.querySelector('#page-cases .card');if(container)container.innerHTML=caseTable(c)}});
document.addEventListener('change',e=>{if(e.target.id==='casePackFilter'){state.selectedPack=e.target.value;renderCases();persist();}});
document.addEventListener('keydown',e=>{if(e.key==='Escape'){closeDrawer();closeModal();document.getElementById('sidebar').classList.remove('open');document.getElementById('mobileShade').classList.remove('open')}if((e.ctrlKey||e.metaKey)&&e.key.toLowerCase()==='k'){e.preventDefault();state.selectedPack='all';nav('cases');document.getElementById('caseSearch').focus()}});
// This is a standalone, simulated UI. No API calls, authentication, external service calls, or real approvals occur.
render();
})();
